<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { MapPin, Search, ArrowRight, X, Plus, Minus, ShoppingBag, Link, Receipt, Bike, Check, RefreshCw } from '@lucide/vue';
interface Place { id:string;name:string;address:string }
interface Dish { id:string;name:string;price_minor:number;packing_minor:number;available:boolean }
interface Shop { id:string;name:string;category:string;icon:string;rating:number;minutes:number;distance_km:number;delivery_minor:number;minimum_minor:number;menu?:Dish[] }
interface Session { authenticated:boolean;connected:boolean;user_id?:string;label?:string;bank_label?:string;place:Place|null;places:Place[] }
interface Order { id:string;shop_name:string;quantity:number;amount_minor:number;status:string;created_at:string;items:{name:string;quantity:number}[];place:Place }
const session=ref<Session>({authenticated:false,connected:false,place:null,places:[]});
const shops=ref<Shop[]>([]),query=ref(''),busy=ref(false),error=ref(''),notice=ref('');
const loginOpen=ref(false),connectOpen=ref(false),phone=ref(''),sms=ref(''),code=ref(''),smsNotice=ref('');
const active=ref<Shop|null>(null),cart=ref<Record<string,number>>({}),tab=ref('附近好店'),orders=ref<Order[]>([]);
const money=(n:number)=>(n/100).toFixed(2);
async function api<T>(path:string,body?:unknown):Promise<T>{
 const headers:Record<string,string>={};if(body!==undefined)headers['Content-Type']='application/json';if(session.value.user_id)headers['x-food-account']=session.value.user_id;
 const response=await fetch('/api/food'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers,body:body===undefined?undefined:JSON.stringify(body)});
 const value=await response.json();if(!response.ok){if(response.status===401){session.value={authenticated:false,connected:false,place:null,places:session.value.places};shops.value=[];orders.value=[];active.value=null;cart.value={};loginOpen.value=true;}throw new Error(typeof value.detail==='string'?value.detail:'请求未完成');}return value;
}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){const next=await api<Session>('/session');if(next.user_id!==session.value.user_id){active.value=null;cart.value={};orders.value=[];}session.value=next;if(next.authenticated&&next.place)await search();else shops.value=[];}
async function search(){if(!session.value.authenticated){loginOpen.value=true;return;}const value=await api<{shops:Shop[]}>('/shops?q='+encodeURIComponent(query.value));shops.value=value.shops;}
async function chooseLocation(event:Event){const id=(event.target as HTMLSelectElement).value;if(!id)return;await run(async()=>{session.value=await api<Session>('/location',{place_id:id});active.value=null;cart.value={};await search();});}
async function sendSMS(){await run(async()=>{const value=await api<{demo_code:string}>('/auth/sms',{phone:phone.value});smsNotice.value=value.demo_code;});}
async function login(){await run(async()=>{await api('/auth/login',{phone:phone.value,code:sms.value});await load();loginOpen.value=false;sms.value='';smsNotice.value='';});}
async function connect(){await run(async()=>{session.value=await api<Session>('/connect',{code:code.value});connectOpen.value=false;code.value='';notice.value='已关联有数账户，可以在有数对话中点餐。';});}
async function logout(){await run(async()=>{await api('/auth/logout',{});active.value=null;cart.value={};orders.value=[];shops.value=[];await load();});}
async function openShop(shop:Shop){await run(async()=>{active.value={...shop,...await api<Shop>('/shops/'+shop.id)};cart.value={};notice.value='';});}
function change(id:string,delta:number){cart.value={...cart.value,[id]:Math.max(0,Math.min(20,(cart.value[id]||0)+delta))};}
const selected=computed(()=>(active.value?.menu||[]).filter(i=>cart.value[i.id]>0));
const count=computed(()=>selected.value.reduce((n,i)=>n+cart.value[i.id],0));
const subtotal=computed(()=>selected.value.reduce((n,i)=>n+cart.value[i.id]*i.price_minor,0));
const packing=computed(()=>selected.value.reduce((n,i)=>n+cart.value[i.id]*i.packing_minor,0));
const instruction=computed(()=>active.value?`帮我在${active.value.name}下单：${selected.value.map(i=>i.name+' '+cart.value[i.id]+'份').join('，')}。`:'');
async function copyInstruction(){try{await navigator.clipboard.writeText(instruction.value);notice.value='点餐指令已复制，请粘贴到有数对话中，核对订单并验证支付密码。';}catch{notice.value='请复制下方点餐指令，粘贴到有数对话中。';}}
async function showOrders(){tab.value='我的订单';await run(async()=>{orders.value=(await api<{orders:Order[]}>('/orders')).orders;});}
async function focus(){if(busy.value)return;try{await load();if(tab.value==='我的订单'&&session.value.authenticated)orders.value=(await api<{orders:Order[]}>('/orders')).orders;}catch{/* explicit refresh displays connection errors */}}
onMounted(()=>{document.title='有数外卖 · 独立演示站';void run(load);window.addEventListener('focus',focus);});
onUnmounted(()=>window.removeEventListener('focus',focus));
</script>

<template>
 <div class="food-app">
  <div class="demo-ribbon">独立外卖沙箱 · 仿美团界面演示 · 虚拟店铺与价格 · 不产生真实订单</div>
  <header><a class="brand" href="/"><span class="brand-icon">外卖</span><span>有数外卖<small>DEMO DELIVERY</small></span></a><div class="location"><MapPin :size="17"/><select aria-label="演示收货位置" :value="session.place?.id||''" :disabled="busy||!session.authenticated" @change="chooseLocation"><option value="" disabled>请选择演示位置</option><option v-for="p in session.places" :key="p.id" :value="p.id">{{ p.name }}</option></select></div><nav><button :class="{active:tab==='附近好店'}" @click="tab='附近好店'">附近好店</button><button :class="{active:tab==='我的订单'}" :disabled="!session.authenticated" @click="showOrders"><Receipt :size="16"/>我的订单</button></nav><button v-if="session.authenticated" class="connect" @click="connectOpen=true"><Link :size="15"/>{{session.connected?'已关联有数':'连接有数账户'}}</button><button v-if="!session.authenticated" class="primary" @click="loginOpen=true">手机号登录</button><button v-else class="user" @click="logout">{{session.label}} · 退出</button></header>
  <main>
   <section class="hero"><div><div class="eyebrow"><span></span>美好的一餐，从这里开始</div><h1>今天，想吃点什么？</h1><p>附近的好味道，让你的银行助手帮你安排。</p><form class="search" @submit.prevent="run(search)"><Search :size="21"/><input v-model="query" placeholder="搜索店铺、牛肉面、汉堡、奶茶…" aria-label="搜索外卖" maxlength="60"/><button class="primary" :disabled="busy">找点好吃的<ArrowRight :size="17"/></button></form><div class="hero-tags"><span><Bike :size="15"/>按演示距离推荐</span><span><Check :size="15"/>费用清楚再下单</span><span>仅扣虚拟余额</span></div></div><div class="hero-art"><span class="art-ring"></span><span class="dish dish-one">🍱</span><span class="dish dish-two">🍔</span><span class="dish dish-three">🧋</span><div class="floating-note"><Bike :size="23"/><div>好味道，马上到<small>虚拟配送 · 演示体验</small></div></div></div></section>
   <div v-if="error" class="alert" role="alert">{{error}}<button @click="error=''" aria-label="关闭错误"><X :size="15"/></button></div><div v-if="notice&&!active" class="notice" role="status">{{notice}}</div>
   <template v-if="tab==='附近好店'">
    <div class="section-title"><div><h2>附近好店 <span>NEARBY</span></h2><p>{{session.place?session.place.name+' · '+session.place.address:'先登录并选择演示位置，我们再为你寻找可配送店铺。'}}</p></div><button class="refresh" :disabled="busy||!session.authenticated" @click="run(search)"><RefreshCw :size="15"/>刷新店铺</button></div>
    <div class="categories"><button v-for="c in [{label:'全部美食',q:'',icon:'🍽️'},{label:'生日蛋糕',q:'蛋糕',icon:'🎂'},{label:'米饭快餐',q:'米饭',icon:'🍱'},{label:'面食饺子',q:'面',icon:'🍜'},{label:'汉堡炸鸡',q:'汉堡',icon:'🍔'},{label:'奶茶咖啡',q:'奶茶',icon:'🧋'}]" :key="c.label" :class="{selected:query===c.q}" @click="query=c.q;run(search)"><span>{{c.icon}}</span>{{c.label}}</button></div>
    <div v-if="shops.length" class="shop-grid"><button v-for="shop in shops" :key="shop.id" class="shop-card" @click="openShop(shop)"><div class="shop-cover"><span>{{shop.icon}}</span><small>演示店铺</small><b>{{shop.category.split(' ')[0]}}</b></div><div class="shop-info"><h3>{{shop.name}}</h3><div class="shop-score"><strong>★ {{shop.rating}}</strong><span>{{shop.distance_km}}km · {{shop.minutes}}分钟</span></div><p>起送 ¥{{money(shop.minimum_minor)}} <span>配送 ¥{{money(shop.delivery_minor)}}</span></p><div class="shop-tags"><span>附近好味</span><span>虚拟支付</span></div></div></button></div>
    <div v-else class="empty"><ShoppingBag :size="38"/><h3>{{!session.authenticated?'登录，开启你的美食地图':!session.place?'选择一个演示收货位置':'暂时没有匹配的可配送店铺'}}</h3><p>店铺和配送范围随演示位置变化，未获取你的真实定位。</p><button v-if="!session.authenticated" class="primary" @click="loginOpen=true">手机号登录</button></div>
   </template>
   <template v-else><div class="section-title"><div><h2>我的订单 <span>ORDERS</span></h2><p>与关联有数账户同步，仅展示已实际创建并扣除虚拟余额的订单。</p></div><button class="refresh" @click="showOrders"><RefreshCw :size="15"/>刷新订单</button></div><div v-if="!orders.length" class="empty"><Receipt :size="38"/><h3>还没有演示订单</h3><p>去有数对话中告诉助手你想吃什么，确认支付后会出现在这里。</p></div><article v-for="order in orders" :key="order.id" class="order"><div><h3>{{order.shop_name}}</h3><span class="order-status">{{order.status}}</span></div><p>{{order.items.map(i=>i.name+' × '+i.quantity).join('，')}}</p><p>{{order.place.address}}</p><footer><small>{{order.created_at}} · {{order.id}}</small><strong>{{order.quantity}}份 · 实付 ¥{{money(order.amount_minor)}}</strong></footer></article></template>
   <footer class="page-footer"><strong>有数外卖 · 演示沙箱</strong><span>所有商家、菜品价格与收货地址均为虚构。未接入美团真实下单和配送服务。</span></footer>
  </main>
  <div v-if="loginOpen||connectOpen" class="overlay" @click.self="loginOpen=false;connectOpen=false"><section class="modal" role="dialog" aria-modal="true" :aria-label="loginOpen?'外卖账号登录':'连接有数账户'"><button class="close" aria-label="关闭弹窗" @click="loginOpen=false;connectOpen=false"><X :size="20"/></button><span class="modal-icon">{{loginOpen?'🍽️':'🔗'}}</span><h2>{{loginOpen?'登录你的美食账户':'连接有数账户'}}</h2><p>{{loginOpen?'独立外卖账号，手机号短信验证后自动创建。':'在有数应用设置生成“平台通用同步码”，在这里输入。'}}</p><form v-if="loginOpen" @submit.prevent="login"><label>手机号<input v-model="phone" inputmode="tel" pattern="1[0-9]{10}" maxlength="11" required placeholder="演示账号 11111111111"/></label><label>短信验证码<div class="sms-field"><input v-model="sms" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required/><button type="button" :disabled="busy||!/^1[0-9]{10}$/.test(phone)" @click="sendSMS">获取验证码</button></div></label><button class="primary full" :disabled="busy">登录 / 注册</button></form><form v-else @submit.prevent="connect"><label>8位通用同步码<input v-model="code" inputmode="numeric" pattern="[0-9]{8}" maxlength="8" required/></label><button class="primary full" :disabled="busy">确认关联</button></form><p v-if="error" class="modal-error" role="alert">{{error}}</p></section></div>
  <div v-if="active" class="overlay" @click.self="active=null"><section class="menu-modal" role="dialog" aria-modal="true" aria-label="店铺菜单"><div class="menu-head"><span>{{active.icon}}</span><div><h2>{{active.name}}</h2><p>配送 ¥{{money(active.delivery_minor)}} · 起送 ¥{{money(active.minimum_minor)}} · 约{{active.minutes}}分钟</p></div><button aria-label="关闭菜单" @click="active=null"><X :size="22"/></button></div><div class="menu-list"><article v-for="dish in active.menu" :key="dish.id"><div class="dish-icon">{{active.icon}}</div><div class="dish-name"><h3>{{dish.name}}</h3><small>演示菜品 · 打包费 ¥{{money(dish.packing_minor)}}/份</small><strong>¥{{money(dish.price_minor)}}</strong></div><div class="stepper"><button v-if="cart[dish.id]" :aria-label="'减少'+dish.name" @click="change(dish.id,-1)"><Minus :size="14"/></button><span v-if="cart[dish.id]">{{cart[dish.id]}}</span><button :aria-label="'添加'+dish.name" :disabled="!dish.available||(cart[dish.id]||0)>=20" @click="change(dish.id,1)"><Plus :size="15"/></button></div></article></div><div class="cart"><div><strong>{{count}}份 · ¥{{money(subtotal+packing+(count?active.delivery_minor:0))}}</strong><small>餐费 ¥{{money(subtotal)}} + 打包 ¥{{money(packing)}} + 配送 ¥{{money(count?active.delivery_minor:0)}}</small></div><button class="primary" :disabled="!count||subtotal<active.minimum_minor" @click="copyInstruction">生成有数点餐指令<ArrowRight :size="17"/></button></div><div v-if="count" class="instruction"><p>复制给有数，核对确认卡并验证支付密码后下单：</p><textarea readonly :value="instruction" aria-label="有数点餐指令"></textarea></div><p v-if="notice" class="notice" role="status">{{notice}}</p></section></div>
  <div v-if="smsNotice" class="sms-notice" role="status"><strong>演示短信 · 有数外卖</strong><button aria-label="关闭短信提示" @click="smsNotice=''"><X :size="15"/></button><p>验证码 <b>{{smsNotice}}</b>，5分钟内有效。</p><small>模拟短信，没有发送到真实手机。</small></div>
 </div>
</template>

<style>
:root{font-family:'Manrope Variable','Microsoft YaHei',sans-serif;color:#242521;background:#f8f8f5;font-synthesis:none}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer;border:0;background:none;color:inherit}button:disabled{opacity:.45;cursor:not-allowed}button,input,select,textarea{outline-color:#c69c17}button{display:inline-flex;align-items:center;justify-content:center;gap:7px}a{color:inherit;text-decoration:none}.demo-ribbon{text-align:center;background:#292a25;color:#d6d7ce;font-size:11px;padding:9px;letter-spacing:.6px}header{max-width:1320px;margin:auto;padding:23px 30px;display:flex;align-items:center;gap:26px}.brand{display:flex;align-items:center;gap:11px;font-size:23px;font-weight:850;white-space:nowrap}.brand small{display:block;font-size:8px;letter-spacing:2.5px;color:#77796c;margin-top:4px}.brand-icon{display:grid;place-items:center;background:#ffd539;border-radius:15px;width:49px;height:49px;font-size:16px;transform:rotate(-5deg)}.location{display:flex;align-items:center;gap:5px;font-size:12px}.location select{border:0;background:transparent;max-width:220px;font-size:12px;color:#65665a}nav{display:flex;gap:20px;margin-left:auto}nav button{font-size:13px;white-space:nowrap;padding:10px 0}nav .active{font-weight:750;border-bottom:3px solid #ffd539}.connect{border:1px solid #dedfd6;border-radius:8px;padding:10px;font-size:12px;white-space:nowrap}.user{font-size:11px;color:#727368;max-width:150px}.primary{background:#ffd43b;border-radius:9px;padding:13px 19px;font-weight:750;font-size:13px;white-space:nowrap}.primary:hover:not(:disabled){background:#ffca14}main{max-width:1220px;margin:0 auto;padding:12px 28px 25px}.hero{background:#f4edda;border:1px solid #eae3ce;border-radius:24px;display:grid;grid-template-columns:1.4fr 1fr;overflow:hidden;min-height:302px;padding:40px 43px;position:relative}.eyebrow{font-size:11px;letter-spacing:2px;color:#82744e;display:flex;align-items:center;gap:8px}.eyebrow span{w